#pragma once
#include <3ds/types.h>

// Anti-aliased 8-bit alpha bitmap fonts, generated by tools/genfont.swift.
typedef struct
{
	u16 code;   // Unicode code point
	u8 w, h;    // bitmap size
	s8 x, y;    // bitmap top-left relative to the pen on the baseline
	u16 adv;    // advance in 1/16 px
	u32 offset; // into the font's bitmap
} Glyph;

typedef struct
{
	const Glyph *glyphs; // sorted by code
	int count;
	const u8 *bitmap;
	int ascent, descent;
} Font;

extern const Font fontSmall, fontBody, fontTitle, fontHuge;
